Definition kinv_inner_exitV (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a6 a7 s2 s3 s4 s8 s9 s10 s11 t3 t4 t5 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (rd sx : Z) (vr : Z -> Z) : machine_state -> Prop :=
  fun ms' => exists (s1' a4' a5' s5' s6' s7' t6' : word) (F' : bvmap 5 word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1' a0 a1 a2 a3 a4' a5' a6 a7 s2 s3 s4 s5' s6' s7' s8 s9 s10 s11 t3 t4 t5 t6')
             F' (Z_to_bv 64 0xcdee8) fc None m' (seg_rom asegs)
    /\ fs_agree F F' /\ munch [(rd, rd + 4 * sx)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ (forall q, 0 <= q < sx -> rw_cells asegs m' (rd + 4 * q) [C4 (Z_to_bv 64 (vr (sx - 1 - q)))]).

Lemma kinv_innerV : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t2 s0 a0 a1 a4 a5 a6 s5 s6 s7 s8 s9 s10 s11 t3 t5 : word) F fc (m : mem) (rs rd sx ps pdf dd i8 : Z) (vr : Z -> Z),
  Z.of_nat k = sx - j -> 0 <= j -> (1 <= k)%nat -> 0 < sx <= 20000 ->
  0 < rs -> rs mod 16 = 0 -> rs + 4 * sx <= 2^47 -> (rs + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= rs) ->
  0 < rd -> rd mod 16 = 0 -> rd + 4 * sx <= 2^47 -> (rd + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= rd) ->
  (rs + 4 * sx <= rd \/ rd + 4 * sx <= rs) ->
  0 < ps -> ps mod 8 = 0 -> ps + 8 <= 2^47 -> (ps + 8 <= 0x7fff7000 \/ 0x10007fff8000 <= ps) -> (ps + 8 <= rd \/ rd + 4 * sx <= ps) ->
  0 < pdf -> pdf mod 8 = 0 -> pdf + 8 <= 2^47 -> (pdf + 8 <= 0x7fff7000 \/ 0x10007fff8000 <= pdf) -> (pdf + 8 <= rd \/ rd + 4 * sx <= pdf) ->
  0 < dd -> 0 <= i8 < 2^20 -> (dd + i8) mod 8 = 0 -> dd + i8 + 8 <= 2^47 -> (dd + i8 + 8 <= 0x7fff7000 \/ 0x10007fff8000 <= dd + i8) -> (dd + i8 + 8 <= rd \/ rd + 4 * sx <= dd + i8) ->
  rw_cells asegs m ps [C8 (Z_to_bv 64 rs)] -> acc asegs m ps 8 ->
  rw_cells asegs m pdf [C8 (Z_to_bv 64 dd)] -> acc asegs m pdf 8 ->
  rw_cells asegs m (dd + i8) [C8 (Z_to_bv 64 rd)] -> acc asegs m (dd + i8) 8 ->
  wr_at asegs m rs (4 * sx) -> acc asegs m rs (4 * sx) -> wr_at asegs m rd (4 * sx) -> acc asegs m rd (4 * sx) -> mem_inv asegs m ->
  (forall q, 0 <= q < sx -> rw_cells asegs m (rs + 4 * q) [C4 (Z_to_bv 64 (vr q))]) ->
  (forall q, 0 <= q < j -> rw_cells asegs m (rd + 4 * q) [C4 (Z_to_bv 64 (vr (sx - 1 - q)))]) ->
  evt asegs (kinv_inner_exitV ra sp gp tp t0 (Z_to_bv 64 (sx * 4)) t2 s0 a0 a1 (Z_to_bv 64 pdf) (Z_to_bv 64 ps) a6 (Z_to_bv 64 (sx + -1)) (Z_to_bv 64 i8)
               (Z_to_bv 64 2147450880) (Z_to_bv 64 (ps / 8 + 2147450880)) s8 s9 s10 s11 t3 (Z_to_bv 64 (pdf / 8 + 2147450880)) t5 F fc m rd sx vr)
    (MS (mkR ra sp gp tp t0 (Z_to_bv 64 (sx * 4)) t2 s0 (Z_to_bv 64 j) a0 a1 (Z_to_bv 64 pdf) (Z_to_bv 64 ps) a4 a5 a6 (Z_to_bv 64 (sx + -1))
             (Z_to_bv 64 i8) (Z_to_bv 64 2147450880) (Z_to_bv 64 (ps / 8 + 2147450880)) s5 s6 s7 s8 s9 s10 s11 t3 (Z_to_bv 64 (pdf / 8 + 2147450880)) t5 (Z_to_bv 64 (4 * j)))
        F (Z_to_bv 64 0xcddd8) fc None m (seg_rom asegs)).
